// Recovered from the July 20 Deckplate/AI Lantern session (regenerated by transcript replay).
const fs = require('fs'); const path = require('path');
const { JSDOM } = require("jsdom");
const dom = new JSDOM(fs.readFileSync(require("path").join(__dirname, "..", "src", "lantern.inner.html"),'utf8'),
  { runScripts:'dangerously', url:'http://localhost/', pretendToBeVisual:true });
const w = dom.window, d = w.document;
w.HTMLMediaElement.prototype.play = function(){ return Promise.resolve(); };
w.HTMLMediaElement.prototype.pause = function(){};
let fails = 0;
const check = (n,c) => { console.log((c?'PASS':'FAIL')+'  '+n); if(!c) fails++; };
(async () => {
  d.dispatchEvent(new w.Event('DOMContentLoaded', {bubbles:true}));
  await new Promise(r=>setTimeout(r,30));
  w.location.hash = 'deckplate'; w.dispatchEvent(new w.Event('hashchange'));
  await new Promise(r=>setTimeout(r,60));
  const DP = w.Lantern.DP; DP.closeModal();
  const ids = ['dp-lyrpanel','dp-importbar','dp-watchbar','dp-transport','dp-sheet','dp-modal','dp-sheetscrim','dp-modalscrim'];
  for (const id of ids) {
    const el = d.getElementById(id);
    check(id + ' hidden -> computed display none', w.getComputedStyle(el).display === 'none');
  }
  check('library content visible (not covered): dp-content computed display', w.getComputedStyle(d.getElementById('dp-content')).display !== 'none');
  // open lyrics for a playing track -> panel actually shows
  const f = new w.File([fs.readFileSync(require("path").join(__dirname, "fixtures", "t1.mp3"))], 't1.mp3', {type:'audio/mpeg'});
  await DP.importFiles([{file:f, relPath:null}], {});
  d.querySelector('.dp-hit').click();
  await new Promise(r=>setTimeout(r,30));
  check('transport shows when playing', w.getComputedStyle(d.getElementById('dp-transport')).display !== 'none');
  DP.toggleLyrics();
  check('lyrics panel shows when opened', w.getComputedStyle(d.getElementById('dp-lyrpanel')).display === 'flex');
  DP.toggleLyrics();
  check('lyrics panel hides when closed', w.getComputedStyle(d.getElementById('dp-lyrpanel')).display === 'none');
  console.log(fails ? 'REGRESSION FAILURES: '+fails : 'ALL HIDDEN/DISPLAY REGRESSIONS PASS');
  process.exit(fails?1:0);
})().catch(e=>{console.error(e);process.exit(1);});
